class State(TypedDict):
    messages: Annotated[list[AnyMessage], add_messages]
    steps: int
    tokens: int
    last_call: str | None

MAX_STEPS, MAX_TOKENS = 12, 60_000

def guard(state) -> str:
    if state["steps"] >= MAX_STEPS or state["tokens"] >= MAX_TOKENS:
        return "give_up"                       # answer partially, hand off
    return "tools" if state["messages"][-1].tool_calls else "end"

def call_tool(state):
    call = state["messages"][-1].tool_calls[0]
    sig = f"{call['name']}:{hash(str(call['args']))}"
    if sig == state["last_call"]:              # identical repeat: break the loop
        return {"messages": [ToolMessage("Already called with these arguments. "
                                         "Use the previous result or ask the user.",
                                         tool_call_id=call["id"])]}
    return {"messages": [run(call)], "last_call": sig, "steps": state["steps"] + 1}

