@workflow.defn
class ClaimWorkflow:
    @workflow.run
    async def run(self, claim_id: str):
        facts = await workflow.execute_activity(
            gather_evidence, claim_id,
            start_to_close_timeout=timedelta(minutes=5),
            retry_policy=RetryPolicy(maximum_attempts=3))

        assessment = await workflow.execute_activity(     # the agent lives here
            run_agent, facts, start_to_close_timeout=timedelta(minutes=15))

        if assessment.amount > 5_000:
            await workflow.wait_condition(                # days, not seconds
                lambda: self.approved is not None,
                timeout=timedelta(days=3))
            if self.approved is None:
                return await workflow.execute_activity(escalate, claim_id)

        try:
            await workflow.execute_activity(pay, claim_id)   # idempotency key inside
        except ActivityError:
            await workflow.execute_activity(compensate, claim_id)   # saga, not retry

    @workflow.signal
    def approve(self, decision: bool): self.approved = decision

async def answer(user_text, ctx):
    # layer 1: deterministic, microseconds
    if len(user_text) > MAX_INPUT or blocklist.search(user_text):
        return refuse("input_rejected")

    # layer 2: small classifier in parallel with the real call; cancel on trip
    guard = asyncio.create_task(jailbreak_classifier(user_text))
    main  = asyncio.create_task(agent.astream(user_text, ctx))
    verdict = await guard
    if verdict.blocked:
        main.cancel()
        metrics.incr("guardrail.trip", tags=["stage:input", f"rule:{verdict.rule}"])
        return refuse("off_policy")

    # layer 3: stream out, checking a small buffer at a time
    buf = ""
    async for chunk in main:
        buf += chunk
        if len(buf) > 200:
            if pii.detect(buf): return refuse("pii_leak")
            yield buf; buf = ""

# layer 4 (the one that matters): enforcement inside the tool
